// Days user can attend are different from days a starter coach should prescribe.
function availableTrainingDays(p=state.profile){const days=p.availableDays||p.days||[1,3,5];return [...new Set(days)].filter(d=>Number.isInteger(d)&&d>=0&&d<=6).sort((a,b)=>a-b);}
function chooseTrainingDays(available,count){
 const choices=availableTrainingDays({availableDays:available});count=Math.min(choices.length,Math.max(1,count));
 let best=null,lowest=Infinity;
 const walk=(at,selected)=>{if(selected.length===count){
   const gaps=selected.map((d,i)=>(selected[(i+1)%count]+(i===count-1?7:0))-d);
   const ideal=7/count;
   // Prefer reasonably spaced sessions, then familiar weekdays, preserving supplied availability.
   const score=gaps.reduce((v,g)=>v+(g-ideal)**2,0)+selected.filter(d=>d===0).length*.15;
   if(score<lowest){lowest=score;best=[...selected]}return;
  }for(let i=at;i<choices.length;i++)walk(i+1,[...selected,choices[i]]);
 };walk(0,[]);return best||choices.slice(0,count);
}
function trainingRecommendation(p=state.profile){
 const available=availableTrainingDays(p);
 const base=p.experience==='regular'?4:3;
 const count=Math.min(available.length,base);
 const dayList=chooseTrainingDays(available,count);
 const limits=(p.restrictions||[]).length>0;
 const rationale=p.experience==='regular'
 ?'You reported training regularly, so four structured sessions can work if recovery and technique remain good.'
 :'You are starting or returning after time away. Three structured sessions is a manageable starting point to build consistency and leave recovery between harder efforts.';
 const availability=available.length>count?`You are free ${available.length} days, but that does not mean you need to train ${available.length} days.`:`Your availability supports ${count} scheduled ${count===1?'session':'sessions'}.`;
 const caution=limits?' Your reported limitations make gradual progression and symptom-aware adjustments especially important.': '';
 return {count,days:dayList,explanation:`${rationale} ${availability}${caution}`,nextStep:'After about 3–4 consistent weeks, reassess recovery, pain and adherence before adding a structured session. Optional walks or comfortable low-impact activity do not need to be full gym days.'};
}
function saveTrainingFrequency(count){
 const available=availableTrainingDays(),requested=Number(count);
 if(!Number.isInteger(requested)||requested<1||requested>available.length||requested>6)return false;
 const days=chooseTrainingDays(available,requested),today=localDay();
 if(days.join(',')===state.profile.days.join(','))return true;
 if((currentDraft().checks||[]).length&&!confirm('Changing the schedule will clear your unfinished checkmarks for today. Completed workouts will remain. Continue?'))return false;
 // Preserve historical completed sessions exactly as completed, including custom exercises.
 for(const log of Object.values(state.logs))if(log.planId&&!log.planSnapshot){const old=state.templates.find(w=>w.id===log.planId);if(old)log.planSnapshot=JSON.parse(JSON.stringify(old));}
 reconcile();
 state.profile.days=days;state.profile.frequencyChoice=requested;
 state.periods=state.periods.filter(period=>period.start!==today);
 state.periods.push({start:today,days:[...days]});state.periods.sort((a,b)=>a.start.localeCompare(b.start));
 state.templates=buildProgram(state.profile);delete state.drafts[today];ui.extraWorkout=false;
 ui.showFrequencyOptions=false;save();return true;
}
