async function callCoachApi(action,payload){
 const token=coachSessionCode;
 if(!token)throw new Error('Connect your Coach access code in Settings.');
 if(!location.protocol.startsWith('http'))throw new Error('Live AI requires your Netlify-hosted app. This downloaded HTML runs the offline coach only.');
 const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),22000);
 try{
  const res=await fetch('/.netlify/functions/coach',{method:'POST',headers:{'content-type':'application/json','x-coach-access':token},body:JSON.stringify({action,payload}),signal:ctl.signal});
  let data;try{data=await res.json()}catch(e){throw new Error('Coach endpoint returned invalid JSON. Check Netlify Functions deployment.')}
  if(!res.ok)throw new Error(data.error||`Coach service unavailable (${res.status}).`);
  return data;
 }finally{clearTimeout(timer)}
}
async function aiCoachRefresh(question=''){
 if(coachApiBusy)return;coachApiBusy=true;coachApiError='';if(question)coachAskText=question;render();
 try{const snapshot=coachSnapshot();const resp=await callCoachApi('coach',{snapshot,question:question.slice(0,650)});
  if(!resp.report?.assessment)throw new Error('No usable coaching report returned.');
  if(question){coachLiveAnswer=[resp.report.assessment,resp.report.nextAction].filter(Boolean).join(' ')}
  else{state.coachAIReports=state.coachAIReports||{};state.coachAIReports[localDay()]=resp.report;
   for(const d of Object.keys(state.coachAIReports).filter(k=>k<addDays(localDay(),-7)))delete state.coachAIReports[d];save()}
 }catch(e){coachApiError=e?.name==='AbortError'?'Coach request timed out. Try again.':String(e?.message||e)}
 finally{coachApiBusy=false;render()}
}
async function aiFoodEstimate(){const q=($('#quickFood')?.value||ui.foodQuery||'').trim();if(!q){ui.foodError='Describe the food first.';render();return}
 if(coachApiBusy)return;coachApiBusy=true;ui.foodLookupBusy=true;ui.foodError='';ui.foodQuery=q;render();
 try{const rsp=await callCoachApi('food',{description:q});const f=rsp.food;if(!f||!Number.isFinite(+f.calories))throw Error('No reliable estimate available.');
  ui.foodPreview={description:String(f.description).slice(0,180),items:[{name:f.description,calories:f.calories,protein:f.protein,carbs:f.carbs,fat:f.fat,source:'ai-estimate'}],assumptions:[f.serving||'Estimated portion',f.assumptions||'Verify brand, ingredients, and size','AI estimate · not verified restaurant data']};
  ui.foodResults=[];
 }catch(e){ui.foodError=String(e.message||e)}finally{ui.foodLookupBusy=false;coachApiBusy=false;render()}
}
