function finishWorkout(status){const day=localDay(),w=todayWorkout();if(state.logs[day])return;const checks=currentDraft().checks||[];if(status==='done'&&!checks.length)return;state.logs[day]={status:status==='done'?(checks.length>=w.exercises.length?'completed':'partial'):status==='skip'?'skipped':'recovery',planId:w.id,planSnapshot:JSON.parse(JSON.stringify(w)),done:checks,extra:!!state.drafts[day]?.extra||ui.extraWorkout,at:new Date().toISOString(),checkin:checkin()};delete state.drafts[day];ui.tab='today';ui.extraWorkout=false;save();notify(status==='done'?'Session logged. Great work.':status==='skip'?'Missed day recorded. Workout moved to next training day.':'Recovery day recorded. Take care of yourself.')}
