  Object.assign(state.profile,{name:String(values.name||'').trim().slice(0,40),age,heightIn:feet*12+inches,weightLb:wt,sex:['male','female','other','unspecified'].includes(values.sex)?values.sex:'unspecified',experience:['new','returning','regular'].includes(values.experience)?values.experience:'returning'});
