  Object.assign(state.profile,{goalFocus:Object.hasOwn(GOAL_LABELS,values.goalFocus)?values.goalFocus:'general',goalsText:String(values.goalsText||'').trim().slice(0,1500),sessionMinutes:[20,30,40,45,60].includes(+values.sessionMinutes)?+values.sessionMinutes:40,equipment:['gym','home','minimal'].includes(values.equipment)?values.equipment:'gym',trainingTime:['morning','afternoon','evening','flexible'].includes(values.trainingTime)?values.trainingTime:'flexible'});
  ui.onboardStep=3;save();render();window.scrollTo(0,0);break;
