  if(!state.setupComplete){state.profile.startedOn=localDay();state.periods=[{start:localDay(),days:[...state.profile.days]}];state.setupComplete=true;}
  else{state.periods=state.periods.filter(x=>x.start!==localDay());state.periods.push({start:localDay(),days:[...state.profile.days]});state.periods.sort((a,b)=>a.start.localeCompare(b.start));}
  for(const log of Object.values(state.logs)){if(log.planId&&!log.planSnapshot){const old=state.templates.find(w=>w.id===log.planId);if(old)log.planSnapshot=JSON.parse(JSON.stringify(old));}}
  state.templates=buildProgram(state.profile); // Previous completed session logs retain their original templates.
